INSERT INTO Projects(Name,Description,GitLink,ProjectLink, ProjectImg, ProjectLanguages) 
VALUE('Blog','Ik heb deze blog in een aantal weken tijd in elkaar gezet. De Blog is gemaakt met de het javascript framework React, css, php en SQL. Je kan als je een admin van de site bent inloggen en een post toevoegen of aanpassen. Als je een post toevoegd moet je eerst kiezen uit een van de drien categorien news, books of movies. Dit is hetzelfde geval als je een post wilt aanpassen alleen dan kies je niet alleen een categorie maar ook een post. Bij het aanpassen kun je er ook voor kiezen om de post te verwijderen. 
Als bezoeker kun je deze posts bekijken. Op de homepagina kom je meteen bij nieuws. bij books zijn boeken reviews en bij movie zijn movie reviews. 
Alle post worden geladen uit een data base en worden dmv de .map() function dynamisch geladen. 
', 'https://github.com/Jessica-vdz/blog','https://jessuccblog.com/home', 'blog', 'React Javascript Framework, CSS, PHP, HTML, SQL');

INSERT INTO Projects(Name,Description,GitLink,ProjectLink, ProjectImg, ProjectLanguages) 
VALUE ('Better Home', 'Better Home is een project waarbij we in een team van 3 personen hebben gewerkt aan een smart home maken. Dit was mijn eerste project waarbij ik werkte met arduino en php. Ons huisje praatte met onze website waar wij de lampjes aan en uit konden zetten. Ook hadden wij zonnepanelen en een eigen gemaakt zonnescherm. deze werd aangedreven door een servo die wachtte op de input van de ldr die net boven het zonnescherm zat.', 'https://github.com/Jessica-vdz/BetterHome/', 'https://39300.hosts2.ma-cloud.nl/BetterHome/', 'betterhome', 'CSS, HTML, JavaScript, PHP, C');

INSERT INTO Projects(Name, Description,GitLink, ProjectImg, ProjectLanguages) 
VALUE('Burning Voices', 'Dit project heb ik gemaakt voor mijn keuzedeel  Special Input Output waarbij het de bedoeling was om een apparaat te maken waar muziek uit kwam. Burning Voices is een jukebox met een disc die twee kleuren bevat. In de "jukebox" zit een ldr sensor en een led. Als je de disc in de box stopt weerkaatst het licht van de disc af wat de ldr sensor weer opvangt. Doordat de disc verschillende kleuren heeft kijgt hij dus ook verschillende waardes. Elke kleur van de disc heeft zijn eigen mapje met liedjes die de doos dan afspeelt dmv een dfplayer en speaker die ook in de doos zitten. Ik heb er ook een website bij gemaakt die op basis van de muziek data laad op de website.', 'https://github.com/Jessica-vdz/TechSpeeltuin-ToasterBox', 'bv', 'HTML, CSS, JavaScript, C');

INSERT INTO Projects(Name, Description,GitLink,ProjectLink, ProjectImg, ProjectLanguages) 
VALUE ('DnD Character generater','Dit project heb ik in twee dagen in elkaar gezet. Ik heb alle data in json files gezet die ik later gebruikt heb om een item eruit te halen of om iets mee te vergelijken. Bij het generaten van een karakter gebeurt het volgende : je begint met 4 dobblestenen van 6 punten en laat de laagste hiervan weg. Dit heb ik gedaan dmv een for loop en de .sort() function. De uitkomsten hiervan zet in in een object zodat ik er later nog meer mee kan doen. Vervolgens bereken je de modifier. Dit zijn de punten die je bij je ability op of af moet rekenen.
Na dat allemaal bekijkt de rollClass welke abilities de hoogste score hebben en vergelijkt dat met de classes. Als de class de juist ability goed kan gebruiken dan stop hij die class in een array om daar vervolgens een random class uit te kiezen. 
Daarna kiest hij de skills. De json geeft een max aantal die de class mag uitkiezen en kiest hij weer random welke daaruit komt.
Ook kiest hij 1 random wapen. Het programma berekent ook nog de attack en health. De attack berekent hij door + 2 op de attack ability te doen en health door 
de Constitution modifier te pakken uit abilities en dat op te tellen bij de health uit de json.', 'https://github.com/Jessica-vdz/DnD','http://generatednd.nl/', 'dnd', 'JavaScript Framework React, CSS, HTML');

INSERT INTO Projects(Name, Description,GitLink,ProjectLink, ProjectImg, ProjectLanguages) 
VALUE ('Art portfolio', 'Dit portfolio heb ik gemaakt voor een gameartist zodat deze haar werk kan laten zien. De website laad de plaatjes en informatie uit de database. De website map vervolgens door de drie tables heen en zet de allemaal op een rijtje. Ik heb van dat rijtje een caroussel gemaakt met css. Als je over een item in de caroussel heen hovert ( of op drukt als je op mobile zit ) krijg je de informatie van het project te zien. Ik ben momenteel nog met de artist bezig om de rest van haar bestanden en informatie op de website te zetten.','https://lisavanboven.nl/','https://github.com/Jessica-vdz/LisaPortfolio','art', 'JavaScript Framework React, CSS, PHP, HTML')